<script setup lang="ts">
import { computed, nextTick, shallowRef } from 'vue'
import { Head, Link, useForm, usePage } from '@inertiajs/vue3'
import { ArrowDownTrayIcon, CheckCircleIcon, ClipboardDocumentIcon, KeyIcon, ShieldCheckIcon } from '@heroicons/vue/24/outline'
import AuthShell from '../../Components/AuthShell.vue'
import FormErrorSummary from '../../Components/FormErrorSummary.vue'
type TwoFactorPayload = { configured?: boolean; qr_svg?: string | null; manual_key?: string | null; recovery_codes?: string[] | null }
const props = withDefaults(defineProps<{ twoFactor?: TwoFactorPayload; enabled?: boolean; qrCode?: string | null; manualKey?: string | null; recoveryCodes?: string[] | null }>(), { twoFactor: () => ({}), enabled: false, qrCode: null, manualKey: null, recoveryCodes: null })
const page = usePage<{ flash?: { status?: string; recoveryCodes?: string[] } }>(); const configured = computed(() => props.twoFactor.configured ?? props.enabled); const qrCode = computed(() => props.twoFactor.qr_svg ?? props.qrCode ?? ''); const manualKey = computed(() => props.twoFactor.manual_key ?? props.manualKey ?? ''); const recoveryCodes = computed(() => props.twoFactor.recovery_codes?.length ? props.twoFactor.recovery_codes : props.recoveryCodes?.length ? props.recoveryCodes : page.props.flash?.recoveryCodes || [])
const enableForm = useForm({ current_password: '' }); const confirmForm = useForm({ code: '' }); const recoveryForm = useForm({ current_password: '', code: '' }); const recoveryCodesSaved = shallowRef(false); const copyState = shallowRef<'idle' | 'copied' | 'error'>('idle'); const errors = computed(() => ({ ...enableForm.errors, ...confirmForm.errors, ...recoveryForm.errors })); const canGoDashboard = computed(() => configured.value && (!recoveryCodes.value.length || recoveryCodesSaved.value))
function focusSummary() { nextTick(() => document.querySelector<HTMLElement>('[data-error-summary]')?.focus()) }
const copyKeyState = shallowRef<'idle' | 'copied' | 'error'>('idle')
async function copyManualKey() {
  try {
    await navigator.clipboard.writeText(manualKey.value)
    copyKeyState.value = 'copied'
  } catch {
    copyKeyState.value = 'error'
  }
}
function enable() { enableForm.post('/two-factor/setup', { preserveScroll: true, onError: focusSummary }) }
function confirm() { confirmForm.post('/two-factor/confirm', { preserveScroll: true, onError: focusSummary }) }
function regenerate() { recoveryForm.post('/two-factor/recovery-codes', { preserveScroll: true, onSuccess: () => { recoveryForm.reset(); recoveryCodesSaved.value = false }, onError: focusSummary }) }
async function copyRecoveryCodes() { try { await navigator.clipboard.writeText(recoveryCodes.value.join('\n')); copyState.value = 'copied' } catch { copyState.value = 'error' } }
function downloadRecoveryCodes() { const blob = new Blob([recoveryCodes.value.join('\n') + '\n'], { type: 'text/plain;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'orcafacil-codigos-de-recuperacao.txt'; link.click(); URL.revokeObjectURL(url) }
</script>
